C004-invariant: Tauri boundary respected
  ```rust
  // ACT: Walk all .rs files under src/ and check for tauri:: imports
  fn walk_src(dir: &std::path::Path) -> Vec<std::path::PathBuf> {
    let mut files = Vec::new();
    if let Ok(entries) = std::fs::read_dir(dir) {
      for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() && !path.file_name().and_then(|n| n.to_str()).map_or(false, |n| n.starts_with('.')) {
          files.extend(walk_src(&path));
        } else if path.extension().map_or(false, |e| e == "rs") {
          files.push(path);
        }
      }
    }
    files
  }
  let src_dir = std::path::Path::new("src");
  if src_dir.is_dir() {
    for entry in walk_src(src_dir) {
      let content = std::fs::read_to_string(&entry).unwrap_or_default();
      // ASSERT: No tauri:: import in any source file
      assert!(!content.contains("tauri::"), "no tauri import allowed in src/: {:?}", entry);
    }
  }
  ```

